mapper.select:
select * from (SELECT ab.borrow_id, ab.project_id, (select ja.project_number from jc_archive ja where ja.project_id = ab.project_id and rownum=1)project_number, (select ja.project_name from jc_archive ja where ja.project_id = ab.project_id and rownum=1) project_name, (select ja.bp_name from jc_archive ja where ja.project_id = ab.project_id and rownum=1) AS bp_name, ( SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = ab.employee_id ) AS employee_id_n, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = ab.unit_id ) AS unit_id_n, ab.borrow_date, ab.borrow_end_date, ab.borrow_return_status, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'BORROW_RETURN_STATUS' AND code_value = ab.borrow_return_status ) AS borrow_return_status_n, ab.element_class_flag, ab.general_class_flag, ab.warrant_class_flag, ab.management_class_flag, ab.apply_reason, ab.return_date, ab.description, ab.creation_date FROM jc_archive_borrow ab )tab
1=1
and tab.borrow_id = #{borrowId}
and tab.project_number like concat('%',concat(#{projectNumber},'%'))
and tab.project_name like concat('%',concat(#{projectName},'%'))
and tab.bp_name like concat('%',concat(#{bpName},'%'))
and tab.employee_id_n like concat('%',concat(#{employeeIdN},'%'))
and tab.unit_id_n like concat('%',concat(#{unitIdN},'%'))
and tab.borrow_return_status = #{borrowReturnStatus}
and to_char(TAB.borrow_date,'YYYY-MM-DD') >= #{borrowDateFrom}
and to_char(TAB.borrow_date,'YYYY-MM-DD') <= #{borrowDateTo}
and to_char(TAB.return_date,'YYYY-MM-DD') >= #{returnDateFrom}
and to_char(TAB.return_date,'YYYY-MM-DD') <= #{returnDateTo}
and tab.borrow_return_status in ('APPROVED','RETURNED')
order by tab.creation_date desc
